// Home-screen metadata for the read-only shared tracker; no offline data cache.
export function buildCncManifest(token) {
 return {id:'/cnc-tracker/view',name:'PanelStock CNC Tracker',short_name:'CNC Tracker',
  start_url:'/cnc-tracker/view?token='+encodeURIComponent(token),scope:'/cnc-tracker/',
  display:'standalone',background_color:'#f5f5f4',theme_color:'#f5f5f4',
  icons:[192,512].map(size=>({src:'/cnc-tracker/icon-'+size+'.png?v=large-2',sizes:size+'x'+size,type:'image/png',purpose:'any'}))};
}
const icons={"192": "", "512": ""};
export function cncInstallIcon(size) {
 const encoded=icons[size];
 return encoded?Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)):null;
}
